"use client";

// Product detail page with a working checkout. Copy is generated by the Catalog
// & Content agent (draft → approved); pricing comes from the governed catalog.
import { useState } from "react";
import { useParams } from "next/navigation";
import { createCheckout } from "@/lib/api";
import { findProduct, formatOfferPrice } from "@/lib/catalog";
import { AddToCart } from "@/lib/AddToCart";

// Next 15/16 turned the `params` prop into a Promise. A Client Component reads
// route params via the synchronous useParams() hook instead — React 18
// compatible, and avoids the React 19-only use() hook.
export default function ProductPage() {
  const { slug } = useParams<{ slug: string }>();
  const product = findProduct(slug);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function buy() {
    if (!product) return;
    setLoading(true);
    setError(null);
    try {
      // Send the SKU only — the control plane prices it.
      const session = await createCheckout([{ sku: product.slug, quantity: 1 }]);
      // Redirect to Stripe Checkout (live) or the mock success URL (dev/CI).
      window.location.href = session.url;
    } catch (e) {
      setError(e instanceof Error ? e.message : "Checkout failed — please try again.");
      setLoading(false);
    }
  }

  return (
    <article>
      <a href="/" style={{ color: "#9aa6c8" }}>
        ← Back
      </a>
      <h1 style={{ fontSize: 30, marginTop: 12 }}>{product ? product.title : slug}</h1>
      <p style={{ color: "#9aa6c8" }}>
        {product
          ? product.blurb
          : "Description rendered from content_assets. Claims are verified — no fabricated reviews or scarcity."}
      </p>
      {product && (
        <>
          <div style={{ fontSize: 22, color: "#a78bfa", marginTop: 8 }}>
            {formatOfferPrice(product)}
          </div>
          {product.note && (
            <div style={{ color: "#9aa6c8", fontSize: 13, marginTop: 4 }}>{product.note}</div>
          )}
        </>
      )}
      <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
        <button
          onClick={buy}
          disabled={!product || loading}
          style={{
            marginTop: 16,
            padding: "12px 22px",
            borderRadius: 10,
            border: "1px solid rgba(124,150,255,.3)",
            background: "linear-gradient(180deg,rgba(124,150,255,.3),rgba(124,150,255,.08))",
            color: "#fff",
            cursor: !product || loading ? "not-allowed" : "pointer",
            opacity: !product || loading ? 0.6 : 1,
          }}
        >
          {loading ? "Starting checkout…" : "Buy now"}
        </button>
        {product && <AddToCart product={product} />}
      </div>
      {error && (
        <p role="alert" style={{ color: "#f87171", marginTop: 12 }}>
          {error}
        </p>
      )}
    </article>
  );
}
